import{_ as e,o as r,c as a,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-06-15","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-06-15","date":"2020-06-15T00:00:00.000Z","updated":"2020-06-16T00:00:00.000Z","tags":["Ceph","Orchestrator","Distributed Storage","DevOps","Kubernetes"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-06-15.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-06-15.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-06-15.md"};function i(s,t,n,u,h,p){return r(),a("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期</strong>: 2020年6月15日</li><li><strong>参会人员</strong>: [参会人员名单]</li><li><strong>主持人</strong>: [主持人姓名]</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Sofia Morgan的新需求</strong></p><ul><li>提出了新的需求，具体细节待补充。</li></ul></li><li><p><strong>新增Tautology测试</strong></p><ul><li>讨论了如何轻松添加新的Tautology测试到Ceph中，希望未来能广泛应用。</li></ul></li><li><p><strong>ETCD配置管理</strong></p><ul><li>正在研究ETCD配置管理，认为这是一个重要的功能。</li></ul></li><li><p><strong>Drive Groups规范</strong></p><ul><li>已通过邮件解决了Drive Groups的规范问题，并讨论了在Rook中处理Drive Groups的方法，特别是转换为Kubernetes的Placement规范。</li></ul></li><li><p><strong>开发环境讨论</strong></p><ul><li>讨论了多种开发环境的优缺点，包括使用restart、bootstrap和C start等。</li><li>提出了使用Kay CLI工具来创建和管理开发环境，该工具能够快速设置虚拟机并映射开发文件夹到主机，以便于开发和测试。</li></ul></li><li><p><strong>每日测试运行</strong></p><ul><li>讨论了设置每日自动运行Rook测试的计划，目前正在准备相关基础设施。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>Drive Groups处理</strong>：确认了将Drive Groups转换为Kubernetes Placement规范的方法，并将在Rook中实施。</li><li><strong>开发环境</strong>：鼓励使用Kay CLI工具来设置开发环境，并计划完善相关文档和演示。</li><li><strong>每日测试</strong>：将继续推进每日自动运行Rook测试的计划，确保测试的持续性和可靠性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>Drive Groups实施</strong>：Sebastian将跟进Drive Groups的实施细节。</li><li><strong>开发环境优化</strong>：Sumukha将准备关于使用Kay CLI工具的演示，并更新开发文档。</li><li><strong>每日测试设置</strong>：Paul Miguel将继续推进每日测试的自动化设置。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>会议中还讨论了一些其他小议题，但未形成具体决议。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在确认无其他议题后结束，并约定下周再次开会。</li></ul><p>会议纪要准确反映了原始内容的要点，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。没有发现明显的错误、误解或遗漏的重要信息。</p>',14)])])}const c=e(o,[["render",i]]);export{d as __pageData,c as default};
